def order_list(request):
    orders = Order.objects.filter(customer=request.user.customer)
    rows = []
    for o in orders:
        rows.append({
            'id': o.id,
            'total': sum(i.price * i.qty for i in o.items.all()),
            'shipper': o.shipment.carrier.name,
            'status': o.status,
        })
    return JsonResponse({'orders': rows})
